            }
            attempt = attempt.saturating_add(1);
        }
        // Raw pointer, not `&T` — same argument-protector
        // rationale as the SPSC ReadSlot.
        let msg = slot_ptr(self.slots, c, self.mask, self.slot_size) as *const T;
