    consumer_idx: CacheAligned<AtomicU32>,
    /// App-owned scratch line ([`USER_WORDS`] words): zeroed by
    /// init, then never touched by the crate.
    user: CacheAligned<[AtomicU32; USER_WORDS]>,
}

